describe('Cookie Consent Banner - Disappearance After Acceptance', () => {
  beforeEach(() => {
    cy.visit('/cookie-consent');
  });

  it('should hide the cookie consent banner after user accepts', () => {
    // Verify the banner is visible initially
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible');
    cy.get('[data-testid="cookie-consent-accept-button"]').should('be.visible');

    // Intercept the consent API call
    cy.intercept('POST', '/api/consent/accept').as('acceptConsent');

    // Click the accept button
    cy.get('[data-testid="cookie-consent-accept-button"]').click();

    // Wait for the API call to complete
    cy.wait('@acceptConsent');

    // Verify the banner is hidden
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist');

    // Verify the consent was recorded
    cy.get('[data-testid="consent-status-indicator"]').should('contain', 'Consent Granted');

    // Verify the user can interact with the page
    cy.get('[data-testid="main-content"]').should('be.visible');
  });

  it('should not hide the banner if user declines or closes it', () => {
    // Verify the banner is visible
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible');

    // Intercept the decline API call
    cy.intercept('POST', '/api/consent/decline').as('declineConsent');

    // Click the decline button
    cy.get('[data-testid="cookie-consent-decline-button"]').click();

    // Wait for the API call to complete
    cy.wait('@declineConsent');

    // Verify the banner remains visible
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible');

    // Verify the consent was not recorded
    cy.get('[data-testid="consent-status-indicator"]').should('contain', 'Consent Declined');

    // Verify the user can interact with the page
    cy.get('[data-testid="main-content"]').should('be.visible');
  });
});
